from itertools import product
from typing import Sequence, Tuple

def step(rule: int, x: Sequence[int]) -> Tuple[int, ...]:
    n = len(x)
    if n < 1: raise ValueError("nonempty cycle required")
    return tuple((rule >> (4*x[(i-1)%n] + 2*x[i] + x[(i+1)%n])) & 1 for i in range(n))

def survivors() -> list[int]:
    answer = []
    for w in range(256):
        if all(len({step(w, x) for x in product((0,1), repeat=n)}) == 2**n for n in range(1,5)):
            answer.append(w)
    return answer

if __name__ == "__main__": print(survivors())

