from typing import Sequence, Tuple

def step(rule: int, x: Sequence[int]) -> Tuple[int, ...]:
    n = len(x)
    if n < 1: raise ValueError("nonempty cycle required")
    return tuple((rule >> (4*x[(i-1)%n] + 2*x[i] + x[(i+1)%n])) & 1 for i in range(n))

def orbit(rule: int, x: Tuple[int, ...], count: int) -> list[Tuple[int, ...]]:
    out = [x]
    for _ in range(count): out.append(step(rule, out[-1]))
    return out

if __name__ == "__main__":
    seed = (1,0,1,1,0,0,1)
    for w in (15,51,85,170,204,240): print(w, orbit(w,seed,4))

